import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [datos, setDatos] = useState(null);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    // Petición al backend Laravel
    axios.get('http://127.0.0.1:8000/api/saludo')
      .then(response => {
        setDatos(response.data);
        setCargando(false);
      })
      .catch(error => {
        console.error('Error:', error);
        setCargando(false);
      });
  }, []);

  return (
    <div className="App">
      <header className="App-header">
        <h1>🚀 React + Laravel API</h1>

        {cargando ? (
          <p>Cargando datos del servidor...</p>
        ) : datos ? (
          <div style={{ textAlign: 'left', background: '#1a1a2e', padding: '20px', borderRadius: '10px' }}>
            <h3>{datos.message}</h3>
            <pre>{JSON.stringify(datos.data, null, 2)}</pre>
            <p><strong>Estado:</strong> {datos.status ? '✅ OK' : '❌ Error'}</p>
          </div>
        ) : (
          <p style={{ color: 'red' }}>No se pudo conectar con el backend</p>
        )}
      </header>
    </div>
  );
}

export default App;
